package validator

import (
	"debug/elf"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"time"
	"unicode/utf8"

	"craftpack/pkg/generator"
	"craftpack/pkg/spec"
	"craftpack/pkg/target/deb"
)

// Options configures project validation.
type Options struct {
	WorkspaceDir string
	SpecPath     string
	Target       string // Optional target filter, e.g. "deb". If empty, all configured targets are validated.
	ConfigOnly   bool   // If true, only validate craftpack.yml schema/syntax, skipping filesystem & asset checks.
	Strict       bool   // If true, treat warnings as hard validation errors.
}

// Result encapsulates the outcome of project validation.
type Result struct {
	Valid    bool                  `json:"valid"`
	SpecPath string                `json:"spec"`
	Package  string                `json:"package"`
	Errors   []string              `json:"errors,omitempty"`
	Warnings []string              `json:"warnings"`
	Config   *spec.CraftpackConfig `json:"-"`
}

// Validate executes full project validation against the specification and workspace assets.
func Validate(opts Options) (*Result, error) {
	specPath := strings.TrimSpace(opts.SpecPath)
	if specPath == "" {
		specPath = "craftpack.yml"
	}

	absSpecPath, err := filepath.Abs(specPath)
	if err != nil {
		return nil, fmt.Errorf("failed resolving specification path %q: %w", specPath, err)
	}

	workspaceDir := opts.WorkspaceDir
	if workspaceDir == "" {
		workspaceDir = filepath.Dir(absSpecPath)
	}
	absWorkspace, err := filepath.Abs(workspaceDir)
	if err != nil {
		return nil, fmt.Errorf("failed resolving workspace directory %q: %w", workspaceDir, err)
	}

	res := &Result{
		Valid:    true,
		SpecPath: specPath,
		Errors:   make([]string, 0),
		Warnings: make([]string, 0),
	}

	// -------------------------------------------------------------------------
	// Tier 1: Specification & Schema Validation
	// -------------------------------------------------------------------------
	parseOpts := spec.ParseOptions{
		WorkspaceDir:   absWorkspace,
		CheckWorkspace: !opts.ConfigOnly,
		Strict:         opts.Strict,
	}

	parseRes, err := spec.ParseFile(absSpecPath, parseOpts)
	if err != nil {
		res.Valid = false
		res.Errors = append(res.Errors, err.Error())
		return res, nil
	}

	cfg := parseRes.Config
	if cfg != nil {
		res.Package = cfg.Name
		res.Config = cfg
	}
	if len(parseRes.Warnings) > 0 {
		res.Warnings = append(res.Warnings, parseRes.Warnings...)
	}

	// In config-only mode, schema validation is sufficient.
	if opts.ConfigOnly {
		if len(res.Errors) > 0 || (opts.Strict && len(res.Warnings) > 0) {
			res.Valid = false
		}
		return res, nil
	}

	// -------------------------------------------------------------------------
	// Tier 2: Workspace & Payload Binary Verification
	// -------------------------------------------------------------------------
	validatePayloadAndEntrypoint(cfg, absWorkspace, opts.Strict, res)

	// Documentation / Man Pages compilation check
	validateManPages(cfg, absWorkspace, res)

	// Templates directory syntax check
	validateTemplatesDir(cfg, absWorkspace, res)

	// -------------------------------------------------------------------------
	// Tier 3: Target-Specific Compliance Verification
	// -------------------------------------------------------------------------
	targetFilter := strings.ToLower(strings.TrimSpace(opts.Target))

	if (targetFilter == "" || targetFilter == "deb") && cfg.Targets.Deb != nil {
		validateDebianTarget(cfg, absWorkspace, res)
	}

	// Evaluate final validity based on errors and strict mode warnings
	if len(res.Errors) > 0 || (opts.Strict && len(res.Warnings) > 0) {
		res.Valid = false
	}

	return res, nil
}

// validatePayloadAndEntrypoint inspects payload files, executable bits, and ELF binary hardening.
func validatePayloadAndEntrypoint(cfg *spec.CraftpackConfig, workspaceDir string, strict bool, res *Result) {
	if cfg.PayloadDir == "" || cfg.Entrypoint == "" {
		return
	}

	cleanPayload := filepath.Clean(cfg.PayloadDir)
	cleanEntry := filepath.Clean(cfg.Entrypoint)
	fullEntrypoint := filepath.Join(workspaceDir, cleanPayload, cleanEntry)

	fi, err := os.Stat(fullEntrypoint)
	if err != nil {
		// Already handled by schema validator if CheckWorkspace is enabled, but guard safely
		res.Errors = append(res.Errors, fmt.Sprintf("entrypoint file %q does not exist in payload_dir %q", cfg.Entrypoint, cfg.PayloadDir))
		return
	}

	if fi.IsDir() {
		res.Errors = append(res.Errors, fmt.Sprintf("entrypoint %q is a directory; must be a regular file", cfg.Entrypoint))
		return
	}

	// 1. Executable bit check
	if fi.Mode().Perm()&0111 == 0 {
		msg := fmt.Sprintf("entrypoint file %q has no executable permissions (mode %04o); binary may fail to run when packaged", cfg.Entrypoint, fi.Mode().Perm())
		res.Warnings = append(res.Warnings, msg)
	}

	// 2. ELF binary inspection (if binary is ELF format)
	f, err := os.Open(fullEntrypoint)
	if err != nil {
		return
	}
	defer f.Close()

	var magic [4]byte
	if _, err := io.ReadFull(f, magic[:]); err != nil {
		return
	}

	// Check for ELF magic bytes: 0x7F 'E' 'L' 'F'
	if magic != [4]byte{0x7f, 'E', 'L', 'F'} {
		// Non-ELF file (e.g. shell script, python script, JVM jar) - skip ELF hardening checks
		return
	}

	// Rewind and parse ELF
	if _, err := f.Seek(0, io.SeekStart); err != nil {
		return
	}

	elfFile, err := elf.NewFile(f)
	if err != nil {
		return
	}
	defer elfFile.Close()

	// Check stripping (.symtab section)
	if elfFile.Section(".symtab") != nil {
		msg := fmt.Sprintf("entrypoint binary %q contains unstripped symbol table (.symtab); Debian packaging standards recommend stripped binaries (-ldflags \"-s -w\") to eliminate Lintian 'unstripped-binary-or-object'", cfg.Entrypoint)
		res.Warnings = append(res.Warnings, msg)
	}

	// Check Position Independent Executable (PIE)
	if elfFile.Type != elf.ET_DYN {
		msg := fmt.Sprintf("entrypoint binary %q is not compiled as Position Independent Executable (PIE); Debian packaging standards recommend PIE (-buildmode=pie) to eliminate Lintian 'hardening-no-pie'", cfg.Entrypoint)
		res.Warnings = append(res.Warnings, msg)
	}
}

// validateManPages verifies that all declared manual pages compile cleanly without syntax errors.
func validateManPages(cfg *spec.CraftpackConfig, workspaceDir string, res *Result) {
	if len(cfg.ManPages) == 0 {
		return
	}
	if _, err := generator.SynthesizeAllManPages(cfg, workspaceDir, "1.0.0", time.Now().UTC()); err != nil {
		res.Errors = append(res.Errors, fmt.Sprintf("man pages validation failed: %v", err))
	}
}

// validateTemplatesDir checks that declared template files are valid.
func validateTemplatesDir(cfg *spec.CraftpackConfig, workspaceDir string, res *Result) {
	if cfg.TemplatesDir == "" {
		return
	}

	cleanDir := filepath.Clean(cfg.TemplatesDir)
	fullDir := filepath.Join(workspaceDir, cleanDir)
	entries, err := os.ReadDir(fullDir)
	if err != nil {
		return // Handled by schema validator
	}

	hasTemplate := false
	for _, e := range entries {
		if !e.IsDir() {
			hasTemplate = true
			break
		}
	}
	if !hasTemplate {
		res.Warnings = append(res.Warnings, fmt.Sprintf("templates_dir %q contains no template files", cfg.TemplatesDir))
	}
}

// validateDebianTarget verifies compliance with Debian packaging requirements.
func validateDebianTarget(cfg *spec.CraftpackConfig, workspaceDir string, res *Result) {
	now := time.Now().UTC()

	// 1. Synthesize DEP-5 copyright
	copyrightBytes, err := deb.SynthesizeCopyright(cfg, workspaceDir, now)
	if err != nil {
		res.Errors = append(res.Errors, fmt.Sprintf("Debian DEP-5 copyright synthesis failed: %v", err))
	} else if len(copyrightBytes) == 0 {
		res.Errors = append(res.Errors, "Debian DEP-5 copyright synthesis generated empty output")
	}

	// 2. Check NOTICE file if present
	if noticeData, hasNotice := deb.FindNoticeFile(workspaceDir); hasNotice {
		if !utf8.Valid(noticeData) {
			res.Errors = append(res.Errors, "NOTICE file contains invalid non-UTF-8 sequences")
		}
	}

	// 3. Changelog synthesis pre-flight
	if strings.ToLower(cfg.Changelog) == "none" {
		// Changelog explicitly disabled; nothing to validate
	} else if cfg.Changelog != "" && strings.ToLower(cfg.Changelog) != "auto" {
		cleanCl := filepath.Clean(cfg.Changelog)
		fullCl := filepath.Join(workspaceDir, cleanCl)
		if _, err := os.Stat(fullCl); err != nil {
			res.Errors = append(res.Errors, fmt.Sprintf("custom changelog file %q not found or not readable: %v", cfg.Changelog, err))
		}
	} else {
		// Dynamic Git changelog synthesis check
		clBytes, err := deb.SynthesizeChangelog(cfg, workspaceDir, "1.0.0", now)
		if err != nil {
			res.Warnings = append(res.Warnings, fmt.Sprintf("changelog synthesis warning: %v", err))
		} else if len(clBytes) == 0 {
			res.Warnings = append(res.Warnings, "changelog synthesis produced empty archive")
		}
	}

	// 4. In-memory DEBIAN/control synthesis
	ctrlBytes, err := deb.GenerateControlFromConfig(cfg, "1.0.0", "amd64")
	if err != nil {
		res.Errors = append(res.Errors, fmt.Sprintf("Debian control file generation failed: %v", err))
	} else if len(ctrlBytes) == 0 {
		res.Errors = append(res.Errors, "Debian control file generation produced empty output")
	}

	// 5. In-memory conffiles synthesis
	if _, err := deb.GenerateConffilesFromConfig(cfg); err != nil {
		res.Errors = append(res.Errors, fmt.Sprintf("Debian conffiles generation failed: %v", err))
	}

	// 6. In-memory maintainer scripts validation
	if _, err := deb.GenerateMaintainerScripts(cfg, workspaceDir); err != nil {
		res.Errors = append(res.Errors, fmt.Sprintf("Debian maintainer scripts validation failed: %v", err))
	}
}
